import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Lumen: Consistent Video Relighting and Harmonious Background Replacement with Video Generative Models","description":"","frontmatter":{"title":"Lumen: Consistent Video Relighting and Harmonious Background Replacement with Video Generative Models","arxiv":"2508.12945","date":"2025-08-18","authors":"Jianshu Zeng, Yuxuan Liu, Yutong Feng, Chenxuan Miao, Zixiang Gao, Jiwang Qu, Jianzhang Zhang, Bin Wang, Kun Yuan","categories":"cs.CV","topics":"视频重打光, 物理感知视频生成, 数据构建","outline":[2,2]},"headers":[],"relativePath":"papers/2508.12945.md","filePath":"papers/2508.12945.md","lastUpdated":null}'),l={name:"papers/2508.12945.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="lumen-consistent-video-relighting-and-harmonious-background-replacement-with-video-generative-models" tabindex="-1">Lumen: Consistent Video Relighting and Harmonious Background Replacement with Video Generative Models <a class="header-anchor" href="#lumen-consistent-video-relighting-and-harmonious-background-replacement-with-video-generative-models" aria-label="Permalink to &quot;Lumen: Consistent Video Relighting and Harmonious Background Replacement with Video Generative Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2508.12945" target="_blank" rel="noreferrer">2508.12945</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-08-18</td></tr><tr><td><strong>作者</strong></td><td>Jianshu Zeng, Yuxuan Liu, Yutong Feng, Chenxuan Miao, Zixiang Gao, Jiwang Qu, Jianzhang Zhang, Bin Wang, Kun Yuan</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用 UE5 渲染对 + HDR 模拟对拼出成对重打光视频数据，再靠一个只在合成域激活的 LoRA style adapter 把「渲染味」从光照学习里剥离，让 Wan2.1 端到端做文本可控的视频换背景与打光。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频重打光要同时做两件事：把前景主体的光照改成与新背景一致，同时严格保住前景本身不变的物理属性——albedo、纹理、身份。影视后期和电商视频里这是刚需，抠像换背景之后如果人物身上还留着原场景的冷光，画面立刻塌掉。图像域的 IC-Light 已经把这件事做得相当好，但推到视频就断了：逐帧跑图像模型会让光照在时间上抖动，前景细节逐帧漂移。</p><p>真正卡住这条路的不是模型结构，是数据。要训练一个端到端的视频重打光模型，需要「同一段前景动作 + 不同背景光照」的成对视频，还要配上背景与光照的文本描述和前景 mask。现实世界拿不到这种数据：你没法让同一个人在两个不同的房间里做出逐帧对齐的同一套动作。论文把问题重新定位成一个数据构造问题，这是它最值得注意的地方。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>传统路线依赖 3D 物理仿真，用球谐光照或光传输模拟，需要几何与材质，泛化不到 in-the-wild 视频。学习类方法里，Total Relighting、SwitchLight 这类肖像重打光依赖 light stage 采集与 HDR/SH 表示，控制信号必须是环境贴图，用户无法用一句话描述想要的光。IC-Light 用光传输一致性损失 + 大规模渲染与增强图像训练，第一次让文本/背景图引导的重打光在真实图像上可用，但它是图像模型。</p><p>视频侧有两条：Light-A-Video 免训练地把 IC-Light 抬到视频，设计 Consistent Light Attention 与 Progressive Light Fusion，论文明确指出免训练路线整体质量受限；RelightVid 把 2D 重打光模型膨胀成带时序 attention 的 3D U-Net，作者指出它受制于 in-the-wild 数据质量与底层图像重打光模型自身的缺陷，前景保持与光照一致性都不稳，且文本引导版本未开源，因此本文实验里没有把它列入对比。前人不是没想到用视频模型，而是没有能支撑视频模型训练的成对数据。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>已知事实有三条。第一，大规模视频生成模型（Wan2.1 一类 DiT）已经内生了时序一致的运动先验和电影级质感，如果能把重打光变成一个条件生成任务，时间一致性可以「白拿」。第二，游戏引擎里换环境、换灯光是免费的，UE5 能让同一个角色播同一段动画、走同一条相机轨迹，只改场景与灯光，产出严格对齐的成对视频，并且用特殊材质直接导出干净的前景 mask，不必依赖分割器。第三，IC-Light 已经证明「对真实图像做可控光照退化、把原图当 ground truth」这条自监督路线可行。</p><p>于是自然的组合是：合成域给物理正确的光影变化，真实域给自然的外观分布。但直接混合会有一个可预期的失败模式——只用 3D 数据训出来的模型会把人物渲成塑料感。这不是光照学错了，是域外观分布被一起学进去了。已有的 Still-Moving 恰好给了模板：用一个可插拔的 adapter 去吸收「不该学的那部分分布」。把它接到这里，就得到了 Lumen 的核心设计。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>合成数据同时携带两种信息：正确的光传输规律，和错误的渲染外观分布。前者要学，后者要扔。做法是给模型开一个专门装「渲染味」的口袋——一个 LoRA style adapter，训练时只在合成样本的前向里打开，让它把域外观差异吸收掉；推理时把口袋摘掉，主干里剩下的就是纯粹的重打光能力。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「一段真人在室内走动的手机视频 + 文本 a man in a dimly lit room with blue lighting, neon lighting」为例：</p><ol><li><strong>前景提取</strong>：RMBG-2.0 抽出前景 mask 视频 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，只保留主体，背景内容整块丢弃。</li><li><strong>条件构造</strong>：3D-VAE 编码 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">sr</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⊙</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，与加噪的目标视频 latent 在通道维拼接，DiT 输入投影层相应扩通道；文本由 Qwen2.5-VL-7B 生成的 caption 提供。</li><li><strong>生成</strong>：Wan2.1-Fun-Control 主干按 flow matching 去噪，输出重打光后的完整视频（前景被重打光，背景被文本描述的新场景替换）。</li><li><strong>训练数据两路</strong>：合成路用 UE5 组合 15 个环境（切成 100 个场景）、20 个角色、20 套动画、10 种相机运动，渲出 20,000 段 1920×1080、90 帧（6 秒）视频，组内随机取两段即成一对，可采出至少 100,000 对；真实路收集约 100,000 段 Pexels 等来源的单人视频，先用 uniform-lit restorer 转成均匀白光外观，再用随机 HDR 环境贴图 + 视频法线（NormalCrafter）渲出「被打过光」的退化视频作为输入，原视频作为 ground truth。</li><li><strong>两阶段课程</strong>：阶段一只训 LoRA adapter，输入源视频置零、文本前缀加 &quot;This is a video rendered with a 3D unreal engine&quot;，40,000 步；阶段二冻结 adapter、全参微调 DiT，合成与真实按 1:1 采样，adapter 仅在合成样本的前向中激活，80,000 步。推理时移除 adapter。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>HDR 光照模拟把环境贴图上每个方向的光色写成所有随机采样光源点的余弦衰减叠加：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.5804em;vertical-align:-1.4304em;"></span><span class="mop">min</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="delimsizing size2">(</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8557em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mrel mtight">∈</span><span class="mord mathcal mtight" style="margin-right:0.0822em;">P</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.4304em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">max</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">p</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">cos</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">⟨</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">p</span><span class="mclose mtight">⟩</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">255</span><span class="mord"><span class="delimsizing size2">)</span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">P</span></span></span></span> 是随机采样的光源点集，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">p</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">b</span><span class="mclose">)</span></span></span></span> 是随机光色，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0496em;vertical-align:-0.3552em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">⟨</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">p</span><span class="mclose mtight">⟩</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3552em;"><span></span></span></span></span></span></span></span></span></span> 是球面上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span> 的夹角。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">max</span><span class="mopen">(</span><span class="mord">⋅</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mclose">)</span></span></span></span> 保证背向光源的方向不受照，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">min</span><span class="mopen">(</span><span class="mord">⋅</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">255</span><span class="mclose">)</span></span></span></span> 做过曝截断。整段视频共用一张固定环境贴图，因此模拟出的光照在时间上是一致的——这是它能当视频训练对的前提。</p><p>模型输入是通道拼接：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathrm">concat</span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mopen">[</span><span class="mord mathcal" style="margin-right:0.0894em;">E</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">ϵ</span><span class="mord mathnormal">t</span><span class="mclose">]</span><span class="mpunct">;</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0894em;">E</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">sr</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⊙</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p>第一项是 flow matching 在时刻 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 的插值噪声 latent，第二项是条件。优化目标是标准的速度/噪声回归 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop"><span class="mop">min</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">Θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbb">E</span><span class="mord">∥</span><span class="mord mathnormal">ϵ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0993em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0993em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">Θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mord"><span class="mord">∥</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.4519em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2481em;"><span></span></span></span></span></span></span></span></span></span>。</p><p>评测侧提出 intrinsic consistency：用同一个 uniform-lit restorer <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0993em;">U</span></span></span></span> 把源视频和生成视频都拉回均匀白光，再比相似度</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathrm">sim</span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord mathcal" style="margin-right:0.0993em;">U</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">sr</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⊙</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2329em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0993em;">U</span><span class="mopen">(</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⊙</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p>直觉是：把光照这个混淆变量投影掉之后，剩下的差异就只能来自 albedo 与纹理是否被改动。这让无配对真实视频也能量化前景保持。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>成对视频上，端到端训练是否比免训练/逐帧强？</strong> 在自建的 100 对 3D 视频与 100 对伪配对真实视频上比 IC-Light（逐帧）与 Light-A-Video。真实配对子集上 Lumen 的 PSNR 23.06、LPIPS 0.1083，明显优于 Light-A-Video 的 19.41/0.1717 与 IC-Light 的 18.96/0.1712；VBench 的时序指标三者接近。</p><p><strong>没有 ground truth 时前景保持得怎样？</strong> 在 100 段无配对真实视频上用 intrinsic consistency：Lumen 23.55 / 0.9052 / 0.0650（PSNR/SSIM/LPIPS），Light-A-Video 20.16 / 0.8800 / 0.1141，IC-Light 18.42 / 0.8336 / 0.1210；CLIP-T 0.2342 对 0.1857 与 0.1887。10 人用户研究在前景保持、背景质量、光照协调三项上给出 0.9133 / 0.9267 / 0.9533，平均 0.9311，高于两个 baseline 的 0.8033 与 0.7911。</p><p><strong>多域课程真的必要吗？</strong> 四组消融的定性结论是：只用 3D 数据光影效果好但前景保不住；只用真实数据前景稳但光照与背景不协调；直接混合两者都不理想；加 adapter 才两头兼顾。定量上 CLIP-T 分别为 0.2260 / 0.2323 / 0.2377 / 0.2342，作者自己承认这些指标无法完整反映重打光质量，需结合可视化判断。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：视频重打光的瓶颈是成对数据而非模型结构；UE5 渲染能给出严格对齐但带渲染域偏差的成对视频，HDR 模拟能给出泛化但前景保持无保证的真实域伪对；把两者 1:1 混合直接训会互相污染；一个只在合成样本前向中激活、推理时移除的 LoRA adapter 可以把域外观分布从光照学习中解耦；配套提出的 intrinsic consistency 让无 ground truth 的真实视频也能量化前景保持。</p><p><strong>3 句版</strong>：合成数据教物理，真实数据教外观，adapter 负责让两者不打架。评测上用「拉回均匀光照再比相似度」绕开了没有配对真值的困境。端到端训练的视频模型在前景保持与文本对齐上明显优于把图像重打光模型抬到视频的免训练方案。</p><p><strong>1 句版</strong>：给合成数据配一个可拆卸的「渲染味」口袋，就能同时吃下 3D 渲染的物理正确性与真实视频的外观分布。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最关键的假设是：<strong>渲染域与真实域之间的差异可以被一个低秩 LoRA 完全吸收，且这种吸收不会连带把光影规律一起吃掉</strong>。如果 adapter 在学「渲染味」的同时也学走了一部分光影变化，那么摘掉它之后主干拿到的就是被削弱的重打光能力，方法的核心贡献直接失效。</p><p>论文为此提供的证据主要是定性的：图 5 的可视化显示带 adapter 的结果在前景保持与光照协调上最好。定量证据其实是弱的——消融表里「Mixed w/o Adapter」的 CLIP-T（0.2377）反而略高于完整方案（0.2342），VBench 各项差异也在小数点后三位量级。也就是说，支撑「adapter 有效」这一 claim 的主要是人眼判断和 10 人用户研究，而用户研究并未按消融设置逐项做。可以推断，adapter 的净收益更多体现在人眼敏感但现有指标不敏感的维度（塑料感、皮肤质感），但论文没有给出一个能把这层收益单独量化的指标。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不必复现完整系统。取一个开源 I2V/控制型视频模型（Wan2.1-Fun-Control 或同级），只做小规模验证：</p><ul><li>数据：用任意免费 3D 资产在 Blender/UE 里渲 200 组、每组 4 个不同环境的成对短视频（前景严格对齐）；再从 Pexels 取 2,000 段单人视频，按论文的法线 + 随机 HDR 流程造伪对。</li><li>实现：只训 LoRA（rank 16），做三个 arm——只合成、1:1 混合无 adapter、1:1 混合 + 只在合成前向激活 adapter。</li><li>测量：在 30 段留出真实视频上算 intrinsic consistency（可用任意一致的 delighting 模型代替 uniform-lit restorer），外加一个小规模双盲两两对比（谁的前景更像原人）。</li><li>判据：若 adapter 组在 intrinsic consistency 上不显著优于无 adapter 组，且双盲胜率不超过 60%，则「adapter 解耦域分布」这一机制在小规模下不成立，需怀疑其收益来自训练步数或其他工程细节。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>替代解释：Lumen 的优势可能主要来自<strong>基座模型更强 + 端到端训练</strong>，而不是多域课程。IC-Light 是图像模型，Light-A-Video 是免训练适配，两个 baseline 都没有在视频重打光数据上训练过；把一个 Wan2.1 直接在真实伪对上全量微调（论文的 Only Real Data 组），已经能拿到 CLIP-T 0.2323 与不错的 VBench 分数，与完整方案 0.2342 几乎持平。要证伪，可以只训「Only Real Data」这一个 arm，然后与完整方案一起做同一批人的双盲对比；如果人眼分不出来，那么合成数据与 adapter 的整套机器就变成了可选项。</p><p>可预测的失败场景：强方向性硬光下的投影。HDR 模拟阶段的环境贴图在整段视频中是固定的，训练数据里几乎没有「光源相对被摄体运动」造成的动态阴影；UE5 那一路虽然物理正确，但角色动画与相机轨迹是脚本化的组合。因此当输入视频要求「人走过一盏摆动的灯下」这类光源随时间变化的场景时，可以推断模型会倾向于生成静态一致但物理错误的阴影。论文没有报告这类样本。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：Lumen 把重打光当成一个像素级条件生成任务，光照本身没有被显式表示——用户只能通过文本描述，模型内部也没有可查询的光照状态。这导致两件事做不了：跨镜头保持同一套光照设定；在生成后再微调光照而不重跑整个模型。</p><p><strong>新的 framing</strong>：把视频重打光重构成「估计并编辑一个时变的场景光照场，再让生成器条件于该光照场」，即让模型显式输出一个低维、可编辑的光照表征（例如逐帧的低阶球谐系数或一张随时间演化的环境贴图序列），并以此作为生成的中间瓶颈。可借鉴的相邻领域工具是逆渲染与 relightable Gaussian/NeRF 里成熟的光照参数化，以及扩散模型里 latent bottleneck 的正则化技巧。</p><p><strong>第一个实验</strong>：在现有合成数据上训一个辅助头，从输入视频预测渲染器已知的真值光照参数；然后把生成器的条件从「文本」换成「文本 + 预测光照参数」，检验两件事——(a) 在同一光照参数下，对同一角色的两段不同镜头，前景光照是否比纯文本条件更一致；(b) 手动改动光照参数的方向/色温后，输出是否随之连续变化。若两项都成立，说明光照可以被抽成显式变量而不损失生成质量，视频重打光就从一次性编辑变成了可持续控制的问题。</p>',48)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
